#[path = "solution.rs"]
mod solution;

use solution::{compile_documents, Compilation, CompileError, NamedDocument};

#[test]
fn empty_inputs_produce_direct_empty_object() {
    assert_eq!(
        compile_documents(&[], ""),
        Ok(Compilation { cache_json: "{}".into(), sorted_ids: vec![] })
    );
}

#[test]
fn sorts_documents_and_entries_and_replaces_duplicate_keys() {
    let documents = vec![
        NamedDocument { name: "z".into(), body: "b=first=a\na=2\nb=x=y".into() },
        NamedDocument { name: "a\"\n\r\t\\".into(), body: "k\t=v\"\\\t".into() },
    ];
    let before = documents.clone();
    let result = compile_documents(&documents, " 10\n2\n10\n\n  7  \n").unwrap();

    assert_eq!(result.cache_json, r#"{"a\"\n\r\t\\":{"k\t":"v\"\\\t"},"z":{"a":"2","b":"x=y"}}"#);
    assert_eq!(result.sorted_ids, vec![2, 7, 10]);
    assert_eq!(documents, before);
}

#[test]
fn supports_empty_documents_empty_values_and_u64_boundary() {
    let documents = vec![
        NamedDocument { name: "empty".into(), body: String::new() },
        NamedDocument { name: "value".into(), body: "key=".into() },
    ];
    let ids = u64::MAX.to_string();
    let result = compile_documents(&documents, &ids).unwrap();
    assert_eq!(result.cache_json, r#"{"empty":{},"value":{"key":""}}"#);
    assert_eq!(result.sorted_ids, vec![u64::MAX]);
}

#[test]
fn rejects_empty_and_duplicate_document_names() {
    let empty = vec![NamedDocument { name: String::new(), body: String::new() }];
    assert_eq!(compile_documents(&empty, ""), Err(CompileError::EmptyName));

    let duplicate = vec![
        NamedDocument { name: "doc".into(), body: String::new() },
        NamedDocument { name: "doc".into(), body: "a=1".into() },
    ];
    assert_eq!(compile_documents(&duplicate, ""), Err(CompileError::DuplicateName("doc".into())));
}

#[test]
fn reports_malformed_entry_with_document_and_physical_line() {
    let no_separator = vec![NamedDocument { name: "bad".into(), body: "ok=1\nmissing\nlater=2".into() }];
    assert_eq!(
        compile_documents(&no_separator, ""),
        Err(CompileError::MalformedEntry { document: "bad".into(), line: 2 })
    );

    let empty_key = vec![NamedDocument { name: "empty-key".into(), body: "=allowed-value".into() }];
    assert_eq!(
        compile_documents(&empty_key, ""),
        Err(CompileError::MalformedEntry { document: "empty-key".into(), line: 1 })
    );
}

#[test]
fn rejects_non_decimal_overflow_and_signed_ids_with_line_number() {
    for invalid in ["1\nabc\n3", "1\n18446744073709551616", "+1", "-1", "1.0"] {
        let expected_line = if invalid.starts_with("1\n") { 2 } else { 1 };
        assert_eq!(compile_documents(&[], invalid), Err(CompileError::InvalidId { line: expected_line }));
    }
}

#[test]
fn whitespace_only_id_lines_are_ignored() {
    let result = compile_documents(&[], " \n\t\n 5 \n").unwrap();
    assert_eq!(result.sorted_ids, vec![5]);
}

